def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edges:
        if dst not in adj[src]:
            adj[src].add(dst)
            in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, w in items:
        if w <= 0 or w > limit:
            raise ValueError
    batches = []
    current = []
    current_sum = 0
    for name, w in items:
        if current and current_sum + w > limit:
            batches.append(current)
            current = []
            current_sum = 0
        current.append(name)
        current_sum += w
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '=' found): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

import codecs


def parse_sse(chunks):
    decoder = codecs.getincrementaldecoder('utf-8')()
    parts = []
    for chunk in chunks:
        parts.append(decoder.decode(chunk, False))
    parts.append(decoder.decode(b'', True))
    text = ''.join(parts)

    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    result = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                result.append(data)
            data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            pass

    return result

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Handles extremely large attempt values (e.g. 10**9) without
    constructing a huge integer or overflowing.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("all arguments must be nonnegative")

    # Short-circuit: 0 * 2**n == 0, and min(0, x) == 0
    if base == 0 or cap == 0:
        return 0.0

    # math.ldexp(base, attempt) computes base * 2**attempt directly in
    # floating-point arithmetic without ever building 2**attempt as an
    # intermediate integer.  For overflow it returns inf (or raises
    # OverflowError, which we catch).
    try:
        val = math.ldexp(base, attempt)
    except OverflowError:
        val = math.inf

    return min(float(cap), val)

def fifo_admit(active, queued, budget, slots):
    for req in queued:
        if req > budget:
            raise ValueError(f"Reservation {req} exceeds the whole budget {budget}")

    remaining_tokens = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    remaining = []
    blocked = False

    for req in queued:
        if not blocked and remaining_slots > 0 and req <= remaining_tokens:
            admitted.append(req)
            remaining_tokens -= req
            remaining_slots -= 1
        else:
            blocked = True
            remaining.append(req)

    return admitted, remaining
